1	// Package contractsentinel jsonchars: whole-document validation of the
2	// character legality of a JSON submission.
3	//
4	// encoding/json decodes two classes of illegal input without an error
5	// and silently rewrites the text: an invalid UTF-8 byte inside a JSON
6	// string, and an unpaired (or wrongly ordered) UTF-16 surrogate escape,
7	// are both replaced by U+FFFD. A check note carrying an isolated
8	// high-surrogate escape (such as \uD800) would therefore build a
9	// "successful" report whose evidence no longer matches the submitted
10	// bytes, and a source string hit by the same rewrite would change the
11	// content that feeds the artifact hash. The scan below re-inspects every
12	// raw JSON string literal -- member names and string values, at every
13	// depth, including members dropped later as extension data -- and rejects
14	// the whole submission with a precise location instead of letting any
15	// character be deleted or replaced.
16	package contractsentinel
17	
18	import (
19		"bytes"
20		"encoding/json"
21		"fmt"
22		"unicode/utf8"
23	)
24	
25	// charPathStep locates one JSON value, the same schema-free convention as
26	// dupPathStep: a member step or an array-index step.
27	type charPathStep struct {
28		key   string // member name for an object step; "" for an array step
29		index int    // 0-based array index for an array step; -1 for a member step
30	}
31	
32	const (
33		// charKindEncoding classifies an invalid UTF-8 byte.
34		charKindEncoding = "invalid character encoding"
35		// charKindEscape classifies an unpaired or misordered surrogate escape.
36		charKindEscape = "invalid Unicode escape"
37	)
38	
39	// charEncodingError is a character-legality rejection. kind classifies it as
40	// an encoding or Unicode-escape problem, problem describes the exact cause,
41	// and offset/line/column point at the bad byte or at the backslash of the
42	// offending escape so the submitter can fix the original content.
43	type charEncodingError struct {
44		kind    string
45		problem string // e.g. `unpaired high surrogate escape \uD800`
46		where   string // "member name", "string value" or "input"
47		path    []charPathStep
48		offset  int
49		line    int
50		column  int
51	}
52	
53	func (e *charEncodingError) Error() string {
54		// A whole-document encoding error carries no value path: the bad byte is
55		// in whitespace or another gap outside the string literals.
56		if e.where == "input" && len(e.path) == 0 {
57			return fmt.Sprintf("%s: %s in JSON input (byte offset %d, line %d, column %d)",
58				e.kind, e.problem, e.offset, e.line, e.column)
59		}
60		loc := renderCharPath(e.path)
61		if e.where == "member name" && len(e.path) == 0 {
62			loc = "the top-level object"
63		}
64		return fmt.Sprintf("%s: %s in JSON %s at %s (byte offset %d, line %d, column %d)",
65			e.kind, e.problem, e.where, loc, e.offset, e.line, e.column)
66	}
67	
68	// renderCharPath renders the location as ".key[index].key"; an empty path is
69	// the document root.
70	func renderCharPath(path []charPathStep) string {
71		if len(path) == 0 {
72			return "the top-level value"
73		}
74		var b bytes.Buffer
75		for _, step := range path {
76			if step.index >= 0 {
77				fmt.Fprintf(&b, "[%d]", step.index)
78			} else {
79				b.WriteByte('.')
80				b.WriteString(step.key)
81			}
82		}
83		return b.String()
84	}
85	
86	// validateJSONCharacters scans data and returns the first character-legality
87	// violation in document order: an invalid UTF-8 byte anywhere in the document,
88	// or an unpaired / wrongly ordered surrogate escape inside any JSON string
89	// literal (member names included, at every depth and inside unknown extension
90	// members). It returns nil when no character problem exists; malformed JSON
91	// alone is left for json.Unmarshal to report, which runs right after this
92	// scan, mirroring findDuplicateJSONMember.
93	func validateJSONCharacters(data []byte) *charEncodingError {
94		utf8Err := firstInvalidUTF8Byte(data)
95		escapeErr := scanJSONStringEscapes(data)
96		switch {
97		case escapeErr != nil && (utf8Err == nil || escapeErr.offset <= utf8Err.offset):
98			// On equal offsets the structural message carries the value path.
99			return escapeErr
100		case utf8Err != nil:
101			return utf8Err
102		default:
103			return nil
104		}
105	}
106	
107	// firstInvalidUTF8Byte returns the first byte that is not valid UTF-8. The
108	// byte sweep is structural-blind, so it also covers bytes in whitespace and
109	// gaps that the token walk cannot reach; string-interior bytes found there
110	// lose the offset comparison against the path-qualified error from
111	// scanJSONStringEscapes.
112	func firstInvalidUTF8Byte(data []byte) *charEncodingError {
113		for i := 0; i < len(data); {
114			r, size := utf8.DecodeRune(data[i:])
115			if r == utf8.RuneError && size == 1 {
116				line, column := lineColumn(data, i)
117				return &charEncodingError{
118					kind:    charKindEncoding,
119					problem: fmt.Sprintf("invalid UTF-8 byte 0x%02x", data[i]),
120					where:   "input",
121					offset:  i,
122					line:    line,
123					column:  column,
124				}
125			}
126			i += size
127		}
128		return nil
129	}
130	
131	// scanJSONStringEscapes walks the document token by token and validates every
132	// JSON string literal it reaches, checking both raw UTF-8 validity and
133	// surrogate pairing. It is best-effort over syntax: any decoder error stops
134	// the walk and returns nil, because json.Unmarshal owns syntax errors. String
135	// tokens returned successfully have precise bounds even if a later part of
136	// the document is malformed.
137	func scanJSONStringEscapes(data []byte) *charEncodingError {
138		dec := json.NewDecoder(bytes.NewReader(data))
139		// Keep number literals as text; their bytes are never string content.
140		dec.UseNumber()
141	
142		start := 0
143		tok, err := dec.Token()
144		if err != nil {
145			return nil // malformed JSON: defer to json.Unmarshal
146		}
147		end := int(dec.InputOffset())
148		switch v := tok.(type) {
149		case string:
150			return checkStringToken(data, start, end, nil, false)
151		case json.Delim:
152			if v == '{' {
153				return scanCharObject(dec, data, nil)
154			}
155			if v == '[' {
156				return scanCharArray(dec, data, nil)
157			}
158		}
159		return nil
160	}
161	
162	// scanCharObject scans one JSON object whose opening brace was just consumed.
163	func scanCharObject(dec *json.Decoder, data []byte, path []charPathStep) *charEncodingError {
164		for dec.More() {
165			keyStart := int(dec.InputOffset())
166			keyTok, err := dec.Token()
167			if err != nil {
168				return nil // malformed JSON: defer
169			}
170			keyEnd := int(dec.InputOffset())
171			key, _ := keyTok.(string)
172			memberPath := append(append([]charPathStep(nil), path...), charPathStep{key: key, index: -1})
173			// The member name itself is a JSON string and must be legal even when
174			// the member is an unknown extension that never reaches the decoder.
175			// Its location is the containing object: an unpaired escape in the
176			// name cannot render the name itself, so the path stops at the parent.
177			if e := checkStringToken(data, keyStart, keyEnd, path, true); e != nil {
178				return e
179			}
180			valStart := int(dec.InputOffset())
181			valTok, err := dec.Token()
182			if err != nil {
183				return nil // malformed JSON: defer
184			}
185			valEnd := int(dec.InputOffset())
186			switch v := valTok.(type) {
187			case string:
188				if e := checkStringToken(data, valStart, valEnd, memberPath, false); e != nil {
189					return e
190				}
191			case json.Delim:
192				if v == '{' {
193					if e := scanCharObject(dec, data, memberPath); e != nil {
194						return e
195					}
196				} else if v == '[' {
197					if e := scanCharArray(dec, data, memberPath); e != nil {
198						return e
199					}
200				}
201			}
202		}
203		if _, err := dec.Token(); err != nil { // consume '}'
204			return nil // malformed JSON: defer
205		}
206		return nil
207	}
208	
209	// scanCharArray scans one JSON array whose opening bracket was just consumed.
210	func scanCharArray(dec *json.Decoder, data []byte, path []charPathStep) *charEncodingError {
211		for i := 0; dec.More(); i++ {
212			elemStart := int(dec.InputOffset())
213			elemTok, err := dec.Token()
214			if err != nil {
215				return nil // malformed JSON: defer
216			}
217			elemEnd := int(dec.InputOffset())
218			elemPath := append(append([]charPathStep(nil), path...), charPathStep{index: i})
219			switch v := elemTok.(type) {
220			case string:
221				if e := checkStringToken(data, elemStart, elemEnd, elemPath, false); e != nil {
222					return e
223				}
224			case json.Delim:
225				if v == '{' {
226					if e := scanCharObject(dec, data, elemPath); e != nil {
227						return e
228					}
229				} else if v == '[' {
230					if e := scanCharArray(dec, data, elemPath); e != nil {
231						return e
232					}
233				}
234			}
235		}
236		if _, err := dec.Token(); err != nil { // consume ']'
237			return nil // malformed JSON: defer
238		}
239		return nil
240	}
