243	// JSON string token. The slice may begin with the whitespace or structural
244	// punctuation that separated the token from the previous one, but it always
245	// ends on the token's closing quote and JSON grammar permits no quote in that
246	// prefix, so the first quote byte is the opening quote. isMemberName selects
247	// how the location is described.
248	func checkStringToken(data []byte, start, end int, path []charPathStep, isMemberName bool) *charEncodingError {
249		raw := data[start:end]
250		q := bytes.IndexByte(raw, '"')
251		if q < 0 || raw[len(raw)-1] != '"' {
252			return nil // unreachable for a token returned by encoding/json
253		}
254		openQuote := start + q
255		body := data[openQuote+1 : end-1]
256	
257		where := "string value"
258		if isMemberName {
259			where = "member name"
260		}
