262		// One left-to-right pass over the literal content. Plain bytes are decoded
263		// as UTF-8; backslash escapes are parsed structurally so that a backslash
264		// that escapes another backslash ("\\uD800") is ordinary text, while a
265		// surrogate escape must pair high-before-low with the very next escape.
266		for i := 0; i < len(body); {
267			abs := openQuote + 1 + i
268			b := body[i]
269			if b != '\\' {
