package main

import (
	"fmt"
	"math/rand"
	"os"
)

// deterministically build nested JSON tokens; optionally force a dup key and
// inject a lone surrogate or an invalid byte.
func genVal(r *rand.Rand, depth int, b []byte, forceDup bool) []byte {
	kinds := []string{"obj", "arr", "str", "num", "bool", "null"}
	kind := kinds[r.Intn(len(kinds))]
	if depth > 4 {
		kind = kinds[2+r.Intn(4)]
	}
	switch kind {
	case "obj":
		b = append(b, '{')
		n := r.Intn(4)
		used := map[string]bool{}
		for i := 0; i < n; i++ {
			if i > 0 {
				b = append(b, ',')
			}
			key := fmt.Sprintf("k%d", r.Intn(3)) // small space -> frequent dups
			b = append(b, '"')
			b = append(b, key...)
			b = append(b, '"', ':')
			if forceDup && used[key] {
				// ensure a literal repeated member with scalar children
				b = append(b, '1')
			} else {
				used[key] = true
				b = genVal(r, depth+1, b, forceDup && r.Intn(2) == 0)
			}
		}
		b = append(b, '}')
	case "arr":
		b = append(b, '[')
		n := r.Intn(4)
		for i := 0; i < n; i++ {
			if i > 0 {
				b = append(b, ',')
			}
			b = genVal(r, depth+1, b, forceDup && r.Intn(2) == 0)
		}
		b = append(b, ']')
	case "str":
		b = append(b, '"')
		switch r.Intn(6) {
		case 0:
			b = append(b, []byte(`x\uD800y`)...) // lone high
		case 1:
			b = append(b, []byte(`a\uDC00b`)...) // lone low
		case 2:
			b = append(b, 0xFF)                  // invalid byte
		case 3:
			b = append(b, []byte(`😀`)...) // good pair
		case 4:
			b = append(b, []byte(`\\uD800`)...)     // escaped backslash, ordinary
		default:
			b = append(b, []byte("中文ok")...)
		}
		b = append(b, '"')
	case "num":
		b = append(b, '1')
	case "bool":
		if r.Intn(2) == 0 {
			b = append(b, "true"...)
		} else {
			b = append(b, "false"...)
		}
	default:
		b = append(b, "null"...)
	}
	return b
}

func init() {
	if os.Getenv("FUZZ") != "1" {
		return
	}
	r := rand.New(rand.NewSource(42))
	for i := 0; i < 20000; i++ {
		data := genVal(r, 0, nil, true)
		var dm, cm string
		if dup := findDuplicateJSONMember(data); dup != nil {
			dm = duplicateMemberMessage(data, dup)
		}
		if ce := validateJSONCharacters(data); ce != nil {
			cm = ce.Error()
		}
		fmt.Printf("### %d\nDUP=%q\nCHR=%q\n", i, dm, cm)
	}
	os.Exit(0)
}
EOF
